INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das externe Schema dasselbe wie das konzeptionelle Schema?', 2, '[{"text": "Nein", "correct": true, "because": "Benutzersicht vs. Gesamtsicht"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Ebenen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt das externe Schema?', 3, '[{"text": "Benutzerspezifische Sicht bereitstellen", "correct": true, "because": "Individuelle Datenansicht"}, {"text": "Datenbankstruktur definieren", "correct": false, "because": "Konzeptionelle Ebene"}, {"text": "Physische Speicherung", "correct": false, "because": "Interne Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat das externe Schema?', 5, '[{"text": "Benutzerspezifisch", "correct": true, "because": "Individuelle Sicht"}, {"text": "Abstrakt", "correct": true, "because": "Logische Ansicht"}, {"text": "Physische Speicherung", "correct": false, "because": "Interne Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das externe Schema ist Teil der Drei-Ebenen-Architektur. b) Es beschreibt die physische Speicherung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Physisch interne Ebene"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim externen Schema?', 4, '[{"text": "Benutzersicht", "correct": false, "because": "Kernmerkmal"}, {"text": "Datenabstraktion", "correct": false, "because": "Grundprinzip"}, {"text": "Papiergröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das externe Schema von der physischen Speicherung abhängt?', 2, '[{"text": "Nein", "correct": true, "because": "Abstrakte Ebene"}, {"text": "Ja", "correct": false, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ebene liegt unter dem externen Schema?', 3, '[{"text": "Konzeptionelles Schema", "correct": true, "because": "Logische Struktur"}, {"text": "Internes Schema", "correct": false, "because": "Physisch"}, {"text": "Papierdokumentation", "correct": false, "because": "Keine Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das externe Schema?', 5, '[{"text": "Datensicherheit", "correct": true, "because": "Beschränkte Sicht"}, {"text": "Benutzerfreundlichkeit", "correct": true, "because": "Individuelle Ansicht"}, {"text": "Physische Optimierung", "correct": false, "because": "Interne Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Das externe Schema ist benutzerspezifisch. b) Es enthält die gesamte Datenbankstruktur. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nur Teilansicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein externes Schema?', 4, '[{"text": "Benutzeranforderungen", "correct": false, "because": "Sicht definieren"}, {"text": "Datenbankzugriff", "correct": false, "because": "Zugriff nötig"}, {"text": "Physische Hardware", "correct": true, "because": "Abstrakt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das externe Schema unabhängig vom internen Schema?', 2, '[{"text": "Ja", "correct": true, "because": "Datenunabhängigkeit"}, {"text": "Nein", "correct": false, "because": "Abstraktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat das externe Schema?', 4, '[{"text": "Daten für Benutzer filtern", "correct": true, "because": "Beschränkte Sicht"}, {"text": "Sicherheitskontrolle", "correct": true, "because": "Zugriff einschränken"}, {"text": "Speicheroptimierung", "correct": false, "because": "Interne Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das externe Schema die gesamte Datenbank zeigt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Teilansicht"}, {"text": "Ja", "correct": false, "because": "Benutzerspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim externen Schema?', 3, '[{"text": "Benutzeranforderungen", "correct": true, "because": "Sicht definieren"}, {"text": "Physische Speicherung", "correct": false, "because": "Interne Ebene"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das externe Schema ist benutzerspezifisch. b) Es definiert physische Speicherstrukturen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Physisch interne Ebene"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das externe Schema in der Drei-Ebenen-Architektur?', 5, '[{"text": "Benutzersicht", "correct": true, "because": "Oberste Ebene"}, {"text": "Datenabstraktion", "correct": true, "because": "Logische Sicht"}, {"text": "Speicherzuweisung", "correct": false, "because": "Interne Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim externen Schema unwichtig?', 3, '[{"text": "Benutzerzugriff", "correct": false, "because": "Sicht definieren"}, {"text": "Datenintegrität", "correct": false, "because": "Sicherstellen"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann das externe Schema mehrere Benutzeransichten umfassen?', 3, '[{"text": "Ja", "correct": true, "because": "Verschiedene Sichten"}, {"text": "Nein", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das externe Schema die Datenbankstruktur ändert?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Sicht"}, {"text": "Ja", "correct": false, "because": "Keine Strukturänderung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für das externe Schema zentral?', 4, '[{"text": "Benutzerspezifische Sicht", "correct": true, "because": "Kernprinzip"}, {"text": "Physische Speicherung", "correct": false, "because": "Interne Ebene"}, {"text": "Papierdokumentation", "correct": false, "because": "Irrelevant"}]');
